import{_ as t,o as e,c as o,a0 as r}from"./chunks/framework.Caz7a20Z.js";const u=JSON.parse('{"title":"多智能体网页端跑通啦！这一周收工","description":"多智能体的网页端终于跑通了，其余两篇论文重新评估了一遍，Codex 实在太好用，就是 5 小时限额有点讨厌，明天跟老师讨论一下，这一周就这样过去啦。","frontmatter":{"title":"多智能体网页端跑通啦！这一周收工","date":"2026-08-30T00:00:00.000Z","tags":["日记"],"description":"多智能体的网页端终于跑通了，其余两篇论文重新评估了一遍，Codex 实在太好用，就是 5 小时限额有点讨厌，明天跟老师讨论一下，这一周就这样过去啦。"},"headers":[],"relativePath":"posts/diary-20260830.md","filePath":"posts/diary-20260830.md","lastUpdated":1788080753000}'),s={name:"posts/diary-20260830.md"};function n(d,a,p,i,l,h){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="多智能体网页端跑通啦-这一周收工" tabindex="-1">多智能体网页端跑通啦！这一周收工 <a class="header-anchor" href="#多智能体网页端跑通啦-这一周收工" aria-label="Permalink to &quot;多智能体网页端跑通啦！这一周收工&quot;">​</a></h1><p>今天周日，但收获不小，给这一周结结实实收了个尾 🎉。</p><h2 id="多智能体-网页端终于跑通" tabindex="-1">多智能体：网页端终于跑通！ <a class="header-anchor" href="#多智能体-网页端终于跑通" aria-label="Permalink to &quot;多智能体：网页端终于跑通！&quot;">​</a></h2><p>最大的好消息：<strong>多智能体的网页端终于跑通啦</strong> 🚀！</p><p>之前在本地能跑出结果已经让我偷着乐了，但那是命令行、是&quot;能跑&quot;；今天把网页端也调通了，等于给整套东西套上了一个能看、能点、能交互的壳——从一个&quot;黑框工具&quot;变成了一个&quot;像模像样的应用&quot;。</p><p>从瘫在本地出结果，到能在浏览器里点着玩，这中间差的不是一星半点。智能体这条线，算是真正站起来了嘿嘿 😄。</p><h2 id="其余两篇论文-重新评估了一遍" tabindex="-1">其余两篇论文：重新评估了一遍 <a class="header-anchor" href="#其余两篇论文-重新评估了一遍" aria-label="Permalink to &quot;其余两篇论文：重新评估了一遍&quot;">​</a></h2><p>另外，把<strong>其余那两篇论文重新评估了一遍</strong>。</p><p>之前忙着重头那篇的修改，这两篇沉了一阵子。今天借着 Codex 的东风重新捋了一道，看看现在到底到什么程度、还差哪儿。重新评估完，心里对整体进度又清楚了一截。</p><h2 id="codex-太好用了-就是限额讨厌" tabindex="-1">Codex：太好用了，就是限额讨厌 <a class="header-anchor" href="#codex-太好用了-就是限额讨厌" aria-label="Permalink to &quot;Codex：太好用了，就是限额讨厌&quot;">​</a></h2><p>说到 Codex，必须夸一句：<strong>Codex 太好用啦</strong> 🤖！</p><p>帮我评估论文、理思路、抠细节，效率高得离谱，简直像凭空多了一双手。要不是它，今天这俩活儿怕是还得磨到后半夜。</p><p>唯一的槽点：<strong>现在 5 小时限额太讨厌了</strong> 😤。正顺手呢突然给你掐了，像看剧看到高潮被断网。薅羊毛薅到这个限制上，多少有点意犹未尽——但白嫖还要啥自行车呢哈哈。</p><h2 id="明天跟老师讨论-这一周就这样过去啦" tabindex="-1">明天跟老师讨论，这一周就这样过去啦 <a class="header-anchor" href="#明天跟老师讨论-这一周就这样过去啦" aria-label="Permalink to &quot;明天跟老师讨论，这一周就这样过去啦&quot;">​</a></h2><p>明天的安排很简单：<strong>跟老师讨论讨论</strong>就差不多了。</p><p>把今天这些进展、把多智能体跑通的事、把两篇论文的重新评估，跟老师过一遍，听听下一步往哪走。</p><p>回头一看，<strong>这一周就这么过去了</strong>：论文改完、多智能体从本地到网页端都通了、两篇论文也重新评估了。虽然每天都有坑、有网络有 bug 有睡不够，但一周下来，清单是真的短了一大截。</p><p>这一周，辛苦了，也挺值的。收工，等明天跟老师聊完，再看看下一周能干到哪儿 💪！</p>',18)])])}const _=t(s,[["render",n]]);export{u as __pageData,_ as default};
